const ENTRY_TICKET_NAME = "Entrébiljett";

export const Primary: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    //Wait for 1 seconds to make sure everything is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    //Get the product title of the entry ticket
    const productTitle = canvas.getByText(ENTRY_TICKET_NAME);

    //It should *not* be disabled
    const style = window.getComputedStyle(productTitle);
    const opacity = parseFloat(style.getPropertyValue("opacity"));
    expect(opacity).toEqual(1);
  },
  args: {
    products: [
      {
        ...baseGroupAdmissionProduct,
      },
      {
        ...baseGroupAdmissionProduct,
        productId: 322,
        productName: ENTRY_TICKET_NAME,
        template: {
          templateId: 123,
          highEntrance: false,
        },
      },
    ],
    categoryName: "Vuxen",
    selectedDate: new Date("2034-06-24"),
    selectedValue: "321",
    changeProduct: (product) => console.log(product),
    mockedDate: new Date("2034-06-24T16:00"),
  },
};

export const OpeningHoursHasPassed: Story = {
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);

    //Wait for 1 seconds to make sure everything is loaded
    await new Promise((resolve) => setTimeout(resolve, 1000));

    //Get the product title of the entry ticket that should be disabled
    const productTitle = canvas.getByText(ENTRY_TICKET_NAME);

    //It should be disabled
    const style = window.getComputedStyle(productTitle);
    const opacity = parseFloat(style.getPropertyValue("opacity"));
    expect(opacity).toBeLessThan(1);
  },
  args: {
    ...Primary.args,
    mockedDate: new Date("2034-06-24T17:56"),
  },
};
